def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_times = {}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries that might affect capacity
            expired_keys = [k for k, wt in write_times.items() if wt + ttl <= t]
            for k in expired_keys:
                del cache[k]
                del write_times[k]

            # If key already exists, remove it (we'll re-add it at the end)
            if key in cache:
                del cache[key]
            # If cache is at capacity, evict LRU
            elif len(cache) >= capacity:
                lru_key, _ = cache.popitem(last=False)
                del write_times[lru_key]

            # Add the new entry
            cache[key] = value
            write_times[key] = t

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache and write_times[key] + ttl > t:
                results.append(cache[key])
                # Move to end (most recently used)
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

